/* Skin "perpetuity" (Perpetuity): the tweakcn preset "perpetuity" (Apache-2.0, see NOTICE.md), written by packages/skins/tools/tweakcn-skins.ts.
   On when data-skin="perpetuity" is on <html> (the page) or on any element (a tile of /skins/). Values as tweakcn exports them;
   the spacing scale stays the kit's 0.25rem. Fonts: Source Code Pro (Google Fonts, loaded when the skin is on). */
[data-skin="perpetuity"] {
  --background: hsl(180 21% 93%);
  --foreground: hsl(188.8 78.9% 18.6%);
  --card: hsl(180 24% 96%);
  --card-foreground: hsl(188.8 78.9% 18.6%);
  --popover: hsl(180 24% 96%);
  --popover-foreground: hsl(188.8 78.9% 18.6%);
  --primary: hsl(184 100% 27%);
  --primary-foreground: hsl(0 0% 100%);
  --secondary: hsl(180 29% 88%);
  --secondary-foreground: hsl(188.8 78.9% 18.6%);
  --muted: hsl(180 19% 90%);
  --muted-foreground: hsl(184 35.3% 33.3%);
  --accent: hsl(184 38% 85%);
  --accent-foreground: hsl(188.8 78.9% 18.6%);
  --destructive: hsl(0 62.4% 52%);
  --destructive-foreground: hsl(0 0% 100%);
  --border: hsl(186 27% 85%);
  --input: hsl(180 29% 88%);
  --ring: hsl(184 92% 29%);
  --chart-1: hsl(184 92% 29%);
  --chart-2: hsl(183.5 69.4% 38.4%);
  --chart-3: hsl(183.6 55.1% 48%);
  --chart-4: hsl(184 54% 59%);
  --chart-5: hsl(183.6 55% 70.4%);
  --sidebar: hsl(186 35% 89%);
  --sidebar-foreground: hsl(188.8 78.9% 18.6%);
  --sidebar-primary: hsl(184 92% 29%);
  --sidebar-primary-foreground: hsl(0 0% 100%);
  --sidebar-accent: hsl(184 38% 85%);
  --sidebar-accent-foreground: hsl(188.8 78.9% 18.6%);
  --sidebar-border: hsl(186 27% 85%);
  --sidebar-ring: hsl(184 92% 29%);
  --font-sans: Courier New, monospace;
  --font-serif: Courier New, monospace;
  --font-mono: Courier New, monospace;
  --radius: 0.125rem;
  --shadow-2xs: 1px 1px 2px 0px hsl(185 70% 30% / 0.07);
  --shadow-xs: 1px 1px 2px 0px hsl(185 70% 30% / 0.07);
  --shadow-sm: 1px 1px 2px 0px hsl(185 70% 30% / 0.15), 1px 1px 2px -1px hsl(185 70% 30% / 0.15);
  --shadow: 1px 1px 2px 0px hsl(185 70% 30% / 0.15), 1px 1px 2px -1px hsl(185 70% 30% / 0.15);
  --shadow-md: 1px 1px 2px 0px hsl(185 70% 30% / 0.15), 1px 2px 4px -1px hsl(185 70% 30% / 0.15);
  --shadow-lg: 1px 1px 2px 0px hsl(185 70% 30% / 0.15), 1px 4px 6px -1px hsl(185 70% 30% / 0.15);
  --shadow-xl: 1px 1px 2px 0px hsl(185 70% 30% / 0.15), 1px 8px 10px -1px hsl(185 70% 30% / 0.15);
  --shadow-2xl: 1px 1px 2px 0px hsl(185 70% 30% / 0.38);
  --destructive-hover: hsl(0 62.4% 46%);
}

:is(.dark, [data-theme="dark"]) [data-skin="perpetuity"],
[data-skin="perpetuity"]:is(.dark, [data-theme="dark"]) {
  --background: hsl(196 52% 8%);
  --foreground: hsl(180 77% 61%);
  --card: hsl(192 51% 9.6%);
  --card-foreground: hsl(180 77% 61%);
  --popover: hsl(192 51% 9.6%);
  --popover-foreground: hsl(180 77% 61%);
  --primary: hsl(180 77% 61%);
  --primary-foreground: hsl(196 52% 8%);
  --secondary: hsl(191 59% 21%);
  --secondary-foreground: hsl(180 77% 61%);
  --muted: hsl(193 58% 14%);
  --muted-foreground: hsl(180 51% 43%);
  --accent: hsl(191 59% 21%);
  --accent-foreground: hsl(180 77% 61%);
  --destructive: hsl(357.6 71.5% 48.2%);
  --destructive-foreground: hsl(0 0% 95%);
  --border: hsl(191 59% 21%);
  --input: hsl(191 59% 21%);
  --ring: hsl(180 77% 61%);
  --chart-1: hsl(180 77% 61%);
  --chart-2: hsl(180 51% 43%);
  --chart-3: hsl(180 51% 36%);
  --chart-4: hsl(184 58% 23%);
  --chart-5: hsl(185.2 62.2% 14.5%);
  --sidebar: hsl(196 52% 8%);
  --sidebar-foreground: hsl(180 77% 61%);
  --sidebar-primary: hsl(180 77% 61%);
  --sidebar-primary-foreground: hsl(196 52% 8%);
  --sidebar-accent: hsl(191 59% 21%);
  --sidebar-accent-foreground: hsl(180 77% 61%);
  --sidebar-border: hsl(191 59% 21%);
  --sidebar-ring: hsl(180 77% 61%);
  --font-sans: Source Code Pro, monospace;
  --font-serif: Source Code Pro, monospace;
  --font-mono: Source Code Pro, monospace;
  --shadow-2xs: 1px 1px 2px 0px hsl(180 70% 60% / 0.10);
  --shadow-xs: 1px 1px 2px 0px hsl(180 70% 60% / 0.10);
  --shadow-sm: 1px 1px 2px 0px hsl(180 70% 60% / 0.20), 1px 1px 2px -1px hsl(180 70% 60% / 0.20);
  --shadow: 1px 1px 2px 0px hsl(180 70% 60% / 0.20), 1px 1px 2px -1px hsl(180 70% 60% / 0.20);
  --shadow-md: 1px 1px 2px 0px hsl(180 70% 60% / 0.20), 1px 2px 4px -1px hsl(180 70% 60% / 0.20);
  --shadow-lg: 1px 1px 2px 0px hsl(180 70% 60% / 0.20), 1px 4px 6px -1px hsl(180 70% 60% / 0.20);
  --shadow-xl: 1px 1px 2px 0px hsl(180 70% 60% / 0.20), 1px 8px 10px -1px hsl(180 70% 60% / 0.20);
  --shadow-2xl: 1px 1px 2px 0px hsl(180 70% 60% / 0.50);
  --destructive-hover: hsl(357.6 71.5% 42.2%);
}

[data-skin="perpetuity"] .shadow-xs { --tw-shadow: var(--shadow-xs); }
[data-skin="perpetuity"] .shadow-sm { --tw-shadow: var(--shadow-sm); }
[data-skin="perpetuity"] .shadow { --tw-shadow: var(--shadow); }
[data-skin="perpetuity"] .shadow-md { --tw-shadow: var(--shadow-md); }
[data-skin="perpetuity"] .shadow-lg { --tw-shadow: var(--shadow-lg); }
[data-skin="perpetuity"] .shadow-xl { --tw-shadow: var(--shadow-xl); }
